create or replace view public.phase1_forebet_model_gap_priority with (security_invoker=true) as select tournament, absence_class, count(*)::int as gap_rows, sum(occurrence_count)::int as occurrences, max(last_seen_at) as last_seen_at, case when absence_class='PROVIDER_FIXTURE_OBSERVED_NO_USABLE_MODEL' then 1 when absence_class='PROVIDER_FIXTURE_OBSERVED_NO_MODEL' then 2 when absence_class='PROVIDER_FIXTURE_NOT_IN_FETCHED_MODEL_SURFACE' then 3 else 9 end as repair_priority from public.phase1_identity_gap_classification_v2 where source='FOREBET' and absence_class in ('PROVIDER_FIXTURE_OBSERVED_NO_USABLE_MODEL','PROVIDER_FIXTURE_OBSERVED_NO_MODEL','PROVIDER_FIXTURE_NOT_IN_FETCHED_MODEL_SURFACE') group by tournament,absence_class; revoke all on public.phase1_forebet_model_gap_priority from anon, authenticated;
